style.css:
@-moz-document domain("www.google.com") {
/* Google Hacker Green Glass v1.0.7 | ChatGPT Hacker Green v1.5.3 palette */
html {
  color: #d9ffe6 !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  background-color: #0a0a0a !important;
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

html body, #main, #search, #rcnt, #center_col, #rhs, #appbar,
.L3eUgb, .GyAeWb, .mJxzWe, .sfbg, #islrg, .islrc {
  background-color: transparent !important;
}

html body, h1, h2, h3, h4, label, button, input, select, textarea,
[role="button"], [role="menu"], [role="dialog"], [role="combobox"],
#gb a, #searchform, #search, #rso, #rhs, #hdtb, #foot, #fbar,
.Ij8KCd, .VwiC3b, .yuRUbf, .VuuXrf, .MjjYud, .G43f7e,
.gLFyf, .sbct, .ZtZJ4c, .hPHMGc, .xyEhrf, .sjVJQd {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
}

html body, h1, h2, h3, h4, label, .VwiC3b, .MUxGbd, .VuuXrf,
.NJo7tc, .YrbPuc, .RqT6ge, .gn0F7d {
  color: #d9ffe6 !important;
}

cite, #result-stats, .qLRx3b, .tjvcx, .f, .aCOpRe, .vFhVge,
.YI7COe, .Q8LRLc {
  color: #9ee5b6 !important;
}

a[href], a[href] h3, .GHvYu { color: #7fffac !important; }
#search a:visited h3, #rso a:visited h3 { color: #9ee5b6 !important; }
a[href]:hover, a[href]:hover h3, .GHvYu:hover { color: #00ff66 !important; }
::selection { background-color: rgba(0,255,102,.35) !important; color: #f5fff7 !important; }

/* Recolor the wordmark silhouette before drawing the green glow behind it. */
svg[role="img"][aria-label="Google"], img.lnXdpd, #hplogo img,
#logo img, #logo svg, a.logo img, img.logo[alt="Google"] {
  filter: brightness(0) invert(1) sepia(1) saturate(20)
    hue-rotate(62.2deg) contrast(1.45)
    drop-shadow(0 0 4px rgba(0,255,102,.72))
    drop-shadow(0 0 13px rgba(0,255,102,.42)) !important;
}

/* Search box, with the ChatGPT composer's glass finish. */
.RNNXgb, .A8SBwf .RNNXgb, #searchform .RNNXgb, #searchform .SDkEP {
  color: #d9ffe6 !important;
}

.RNNXgb, #searchform .RNNXgb {
  background-color: rgba(2,33,18,.42) !important;
  background-image: linear-gradient(125deg, rgba(21,100,54,.40), rgba(7,55,30,.28) 48%, rgba(1,20,13,.60)) !important;
  border-color: rgba(85,255,143,.73) !important;
  box-shadow: inset 0 1px 0 rgba(181,255,200,.26), 0 0 14px rgba(0,234,88,.15) !important;
}

.RNNXgb .SDkEP, .RNNXgb .a4bIc, .RNNXgb .gLFyf,
form[role="search"] input[name="q"], form[role="search"] textarea[name="q"],
#searchform input[name="q"], #searchform textarea[name="q"] {
  background: transparent !important;
  color: #d9ffe6 !important;
}

.RNNXgb .SDkEP { box-shadow: none !important; }
.RNNXgb:hover, .RNNXgb:focus-within,
#searchform .RNNXgb:hover, #searchform .RNNXgb:focus-within {
  border-color: #00ff66 !important;
  box-shadow: inset 0 1px 0 rgba(181,255,200,.26), 0 0 18px rgba(0,255,102,.28) !important;
}

.gLFyf::placeholder, input[name="q"]::placeholder,
input[type="text"]::placeholder, input[type="search"]::placeholder {
  color: #9ee5b6 !important;
  opacity: 1 !important;
}

.RNNXgb .iblpc, .RNNXgb .z1asCe, .RNNXgb .goxjub,
.RNNXgb .ExCKkf, .RNNXgb .Gdd5U, #gb .gb_B, #gb .gb_C {
  color: #7fffac !important;
}

/* Search actions and suggestions use explicit colors for legacy parser compatibility. */
.plR5qb, .plR5qb .lTxWLe, .plR5qb .PD3zdc, .dRYYxd,
.aajZCb .aY45Yd, .aajZCb .izN7If, .aajZCb .h8bBW {
  color: #d9ffe6 !important;
}

.plR5qb .bvUkz, .DBqRk, .DBqRk:disabled:hover {
  background-color: rgba(2,26,12,.82) !important;
}

.plR5qb:hover .bvUkz, .DBqRk:hover, .DBqRk:focus-visible {
  background-color: rgba(12,91,39,.56) !important;
}

.plR5qb:focus-visible .bvUkz { outline-color: #00ff66 !important; }

.aajZCb .lh87ke:link, .aajZCb .lh87ke:visited { color: #7fffac !important; }
.aajZCb .ynRric, .aajZCb .w2fKdd { color: #9ee5b6 !important; }

/* Dense menus sit over the page with a near-opaque background. */
.aajZCb, .UUbT9, .mgAbYb, .G43f7e, .cF4V5c, .usJj9c, .qk7LXc,
[role="menu"], [role="dialog"], dialog,
#searchform [role="listbox"], form[role="search"] [role="listbox"] {
  background-color: rgba(2,23,11,.97) !important;
  color: #d9ffe6 !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: 0 8px 26px rgba(0,0,0,.52), 0 0 14px rgba(0,234,88,.15) !important;
}

.aajZCb .G43f7e, .aajZCb [role="listbox"],
[role="dialog"] [role="menu"] {
  background-color: transparent !important;
  box-shadow: none !important;
}

.aajZCb .xtSCL, .UUbT9 .xtSCL, .RNNXgb .ACRAdd {
  border-color: rgba(32,243,107,.18) !important;
}

.wM6W7d, .wM6W7d span, .sbl1, .sbct, .eIPGRd,
[role="menuitem"], [role="option"], .RK9gM {
  color: #d9ffe6 !important;
}

.sbct:hover, .sbct.sbhl, [role="option"]:hover, [role="option"][aria-selected="true"],
[role="menuitem"]:hover, [role="menuitem"]:focus-visible {
  background-color: rgba(12,91,39,.56) !important;
  color: #d9ffe6 !important;
}

/* Header, search filters, navigation and footer. */
#gb, #searchform, .appbar, #hdtb, #fbar, .Ij8KCd, .c93Gbe {
  background-color: rgba(2,26,12,.82) !important;
  color: #9ee5b6 !important;
  border-color: rgba(32,243,107,.18) !important;
}

#gb #searchform, .Ij8KCd #fbar, .Ij8KCd .c93Gbe, .c93Gbe #fbar {
  background-color: transparent !important;
}

#hdtb a, #hdtb [role="button"], .eQtdDf, #fbar a, #fbar button {
  color: #9ee5b6 !important;
}

#hdtb a:hover, #fbar a:hover, .eQtdDf:hover, .pHiOh:hover {
  color: #00ff66 !important;
}

#hdtb [aria-current="page"], #hdtb .hdtb-msel, #hdtb .YmvwI,
[role="tab"][aria-selected="true"] {
  color: #00ff66 !important;
  border-color: #00ff66 !important;
}

#hdtb .hdtb-mitem, #botstuff, #foot, #appbar, hr {
  border-color: rgba(32,243,107,.18) !important;
}

/* Results and related modules. Keep thumbnails, favicons and charts in their original colors. */
.MjjYud, #rso > .g, #search .Gx5Zad,
.kp-wholepage, .knowledge-panel, .ULSxyf .Ww4FFb,
.related-question-pair, .g-blk, .BVG0Nb, .commercial-unit-desktop-rhs {
  background-color: rgba(2,26,12,.82) !important;
  border-color: rgba(32,243,107,.18) !important;
  border-radius: 12px !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
}

.MjjYud, #rso > .g, #search .Gx5Zad {
  padding: 12px 14px !important;
  box-sizing: border-box !important;
  margin-bottom: 12px !important;
}

.MjjYud:hover, #rso > .g:hover, #search .Gx5Zad:hover,
.related-question-pair:hover {
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.36), 0 0 14px rgba(0,234,88,.15) !important;
}

.MjjYud .g, .MjjYud .Ww4FFb,
.kp-wholepage .g-blk, .knowledge-panel .g-blk {
  background-color: transparent !important;
  box-shadow: none !important;
}

#rso .yuRUbf, #rso .VwiC3b, #search .N54PNb, #search .tF2Cxc,
#rhs .kp-header, #rhs .kp-hc, #rhs .wDYxhc {
  background-color: transparent !important;
  border-color: rgba(32,243,107,.18) !important;
}

#rso .iDjcJe, #rso .MUFPAc, #rhs .oIk2Cb, .Wt5Tfe, .k8XOCe {
  background-color: rgba(6,46,22,.84) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #d9ffe6 !important;
}

/* Images grid and preview, video/news carousels and shopping controls. */
#islrg .isv-r, #islrg .H8Rx8c, .islrc .bRMDJf,
#islrg .mJxzWe, #search .WLYqOe, #search .SoaBEf,
#search .dbsr, .sh-dgr__grid-result, .sh-pr__product-results {
  background-color: rgba(2,26,12,.82) !important;
  color: #d9ffe6 !important;
  border-color: rgba(32,243,107,.18) !important;
}

#islrg .isv-r:hover, #islrg .H8Rx8c:hover, #search .SoaBEf:hover,
#search .WLYqOe:hover, .sh-dgr__grid-result:hover {
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.36), 0 0 14px rgba(0,234,88,.15) !important;
}

#islsp, .islsp, .vIciV, #Sva75c .tvh9oe, #Sva75c .HJRshd,
#search .sh-sr__top, #search .sh-fp__container {
  background-color: rgba(2,23,11,.97) !important;
  color: #d9ffe6 !important;
  border-color: rgba(32,243,107,.18) !important;
}

#search .SoaBEf a, #search .WLYqOe a, #islrg .VFACy,
#islrg .mNsIhb, #islsp .BIB1wf, .sh-dgr__content {
  color: #d9ffe6 !important;
}

/* Preferences and Advanced Search. */
.hPHMGc, .xyEhrf, .YgZKtb, .gy6Qzb, .fbar {
  background-color: transparent !important;
  color: #d9ffe6 !important;
  border-color: rgba(32,243,107,.18) !important;
}

#CvDJxb, .lnnMGf, .appbar [role="navigation"], .SzI7Fd {
  background-color: rgba(2,26,12,.82) !important;
  color: #d9ffe6 !important;
  border-color: rgba(32,243,107,.18) !important;
}

#CvDJxb {
  border-radius: 14px !important;
  box-shadow: 0 0 0 1px rgba(32,243,107,.18) !important;
}

#CvDJxb .rULq7d, .lnnMGf, #CvDJxb .mTpL7c {
  border-color: rgba(28,240,102,.36) !important;
}

#CvDJxb .t93dPb, #CvDJxb .DbouRc, #CvDJxb label,
#CvDJxb .uqeVMc, .lnnMGf:hover .vFhVge {
  color: #d9ffe6 !important;
}

.lnnMGf:hover .HrqWPb, .lnnMGf:focus-visible .HrqWPb {
  background-color: rgba(12,91,39,.56) !important;
}

/* Shared controls. Leave Google's control dimensions and icon assets intact. */
input[type="text"], input[type="search"], select, textarea,
#CvDJxb .mTpL7c {
  color: #d9ffe6 !important;
  background-color: rgba(2,26,12,.82) !important;
  border-color: rgba(28,240,102,.36) !important;
}

select option {
  background-color: #02170b !important;
  color: #d9ffe6 !important;
}

input[type="submit"], input[type="button"], .jfk-button,
#searchform .Tg7LZd, #hdtb .t2vtad, #gb a[aria-label="Sign in"], #gb a.gb_A {
  background-color: rgba(6,46,22,.84) !important;
  color: #d9ffe6 !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
}

input[type="submit"]:hover, input[type="button"]:hover, .jfk-button:hover,
#searchform .Tg7LZd:hover,
#hdtb .t2vtad:hover, #gb a[aria-label="Sign in"]:hover, #gb a.gb_A:hover {
  background-color: rgba(12,91,39,.56) !important;
  color: #d9ffe6 !important;
  border-color: #00ff66 !important;
  box-shadow: 0 0 14px rgba(0,234,88,.15) !important;
}

/* Homepage search actions and the basic layout's button frames. */
body .T14B5e input[type="submit"], body .T14B5e button[type="submit"],
body input[name="btnK"], body input[name="btnI"], form[action="/search"] input[name="btnG"],
input.gNO89b, #gbqfbb, .gbqfba, form[action="/search"] .lsbb {
  background: #0d6332 !important;
  color: #e4ffeb !important;
  border-color: #33945a !important;
}

body .T14B5e input[type="submit"]:hover, body .T14B5e button[type="submit"]:hover,
body input[name="btnK"]:hover, body input[name="btnI"]:hover, form[action="/search"] input[name="btnG"]:hover,
input.gNO89b:hover, #gbqfbb:hover, .gbqfba:hover, .gbqfba-hvr,
form[action="/search"] .lsbb:hover {
  background: #168144 !important;
  border-color: #49eb83 !important;
}

/* Homepage shortcut chips below the search box. */
body .CHnH1d .elRzpc[role="button"] {
  background: #0d6332 !important;
  color: #e4ffeb !important;
  border-color: #33945a !important;
  box-shadow: inset 0 0 0 1px #33945a !important;
}
body .CHnH1d .elRzpc[role="button"] .E2vfQc {
  color: inherit !important;
  font-family: inherit !important;
}
body .CHnH1d .elRzpc[role="button"]:hover,
body .CHnH1d .elRzpc[role="button"]:focus-visible {
  background: #168144 !important;
  border-color: #49eb83 !important;
  box-shadow: inset 0 0 0 1px #49eb83, 0 0 12px rgba(0,255,102,.22) !important;
}

#CvDJxb input[type="submit"] {
  background-color: #00e95d !important;
  color: #021108 !important;
  border-color: #00ff66 !important;
}

#CvDJxb input[type="submit"]:hover { background-color: #00ff66 !important; }

a[href]:focus-visible, button:focus-visible, input:focus-visible,
select:focus-visible, textarea:focus-visible, [tabindex]:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}

.RNNXgb .gLFyf:focus-visible { outline: none !important; }

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background-color: #031509; }
::-webkit-scrollbar-thumb { background-color: #216431; border: 2px solid #031509; border-radius: 10px; }
::-webkit-scrollbar-thumb:hover { background-color: #398b52; }
}
